 ReportPreparationCycle nativeCycle(){var base=nativeDay.f.data.nativeData().fixture().f();return new ReportPreparationCycle(new JdbcReportSchedulePages(base.source),nativeDay.service,nativeNoUpdates,base.tx,Clock.fixed(nativeDay.f.data.nativeData().cutoff().plusSeconds(2),ZoneOffset.UTC),()->true);}
 void addNativeDay(){var base=nativeDay.f.data.nativeData().fixture().f();var scope=nativeDay.scope;String id=JdbcFrozenInputs.stableId("intent",scope.logicalKey()+":1");ReportOriginalCompletionTest.utc(()->base.writes.execute(new SharedWriteExecutor.ActionContext("fictional-report-cycle-locator",id,null),k->null,a->new JdbcJobRecords(base.source).ensureIntent(new JdbcJobRecords.Intent(id,scope.logicalKey(),1,"daily_report",scope.day()),nativeDay.f.data.nativeData().cutoff())));}
 @Test void ActualNativeLocatorPreparesTheFullOriginalDailyWithoutSendingOrManufacturingNoUpdate()throws Exception{nativeSetup();addNativeDay();var cycle=nativeCycle();for(int i=0;i<12&&nativeDay.originals.find(nativeDay.scope)==null;i++)ReportOriginalCompletionTest.utc(()->cycle.run(()->true));var original=nativeDay.originals.find(nativeDay.scope);assertNotNull(original);assertEquals("queued",original.input().state());assertEquals(2,nativeDay.f.data.nativeData().fixture().f().sends);assertNull(nativeNoUpdates.find(nativeDay.scope));assertEquals(original,ReportOriginalCompletionTest.utc(()->nativeDay.service.prepare(nativeDay.scope)));}
 @Test void ActualCommittedCompleteNoInputIsObservedAndMissingOriginalNeverGetsNoUpdate()throws Exception{nativeSetup();var base=nativeDay.f.data.nativeData().fixture().f();base.jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",nativeDay.f.data.nativeData().completed().version().contentId());addNativeDay();var cycle=nativeCycle();for(int i=0;i<12&&nativeNoUpdates.find(nativeDay.scope)==null;i++)ReportOriginalCompletionTest.utc(()->cycle.run(()->true));assertNotNull(nativeNoUpdates.find(nativeDay.scope));assertEquals("no_input",nativeDay.originals.find(nativeDay.scope).input().state());assertEquals(2,base.sends);nativeSetup();base=nativeDay.f.data.nativeData().fixture().f();base.jdbc.update("DELETE FROM jobs WHERE target_type='content_availability'");addNativeDay();final var missingCycle=nativeCycle();for(int i=0;i<12;i++)ReportOriginalCompletionTest.utc(()->missingCycle.run(()->true));assertNull(nativeNoUpdates.find(nativeDay.scope));assertNotNull(nativeDay.originals.find(nativeDay.scope));assertFalse(nativeDay.originals.find(nativeDay.scope).input().missing().isEmpty());}
 @Test void RosterSchedulesNaturalPeriodsAtFixedFiveAndEveryPageRevisitsLateInputs()throws Exception{var f=new ReportSchedulePagesTest(){@Override GenerationJdbcStoreTest fixture(){return ReportPreparationCycleTest.this.mysql()?new GenerationJdbcStoreMySqlTest():new GenerationJdbcStoreTest();}};f.setup();var day=LocalDate.parse("2026-01-01");f.add("source_day_roster",day,1);var preparation=mock(ReportPreparationService.class);var noUpdates=mock(ReportNoUpdateProofService.class);var seen=new ArrayList<ReportInputCaptureService.Scope>();when(preparation.prepare(any())).thenAnswer(i->{var scope=i.getArgument(0,ReportInputCaptureService.Scope.class);seen.add(scope);var original=mock(ReportPreparedInputService.Prepared.class);when(original.scope()).thenReturn(scope);return original;});var now=new java.util.concurrent.atomic.AtomicReference<>(Instant.parse("2026-02-01T00:00:00Z"));var clock=mock(Clock.class);when(clock.instant()).thenAnswer(i->now.get());var cycle=new ReportPreparationCycle(new JdbcReportSchedulePages(f.f.source),preparation,noUpdates,new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.f.source),clock,()->true);for(int i=0;i<3;i++)assertEquals(ReportPreparationCycle.Outcome.PREPARED,cycle.run(()->true));assertEquals(List.of("report:daily:2026-01-01","report:weekly:2026-01-04","report:monthly:2026-01-31"),seen.stream().map(ReportInputCaptureService.Scope::logicalKey).toList());verify(noUpdates,times(1)).observe(any());now.set(Instant.parse("2026-01-01T20:59:59.999999Z"));assertEquals(ReportPreparationCycle.Outcome.WAITING,cycle.run(()->true));assertEquals(3,seen.size());assertEquals(ReportPreparationCycle.Outcome.WAITING,cycle.run(()->true));assertEquals(ReportPreparationCycle.Outcome.WAITING,cycle.run(()->true));now.set(Instant.parse("2026-01-01T21:00:00Z"));assertEquals(ReportPreparationCycle.Outcome.PREPARED,cycle.run(()->true));assertEquals(4,seen.size());}
 @Test void GatesStopAndOverlapProtectEveryWriterAndFailuresRemainRecoveryRequired()throws Exception{var f=new ReportSchedulePagesTest(){@Override GenerationJdbcStoreTest fixture(){return ReportPreparationCycleTest.this.mysql()?new GenerationJdbcStoreMySqlTest():new GenerationJdbcStoreTest();}};f.setup();f.add("daily_report",LocalDate.parse("2026-01-01"),1);var preparation=mock(ReportPreparationService.class);var noUpdates=mock(ReportNoUpdateProofService.class);var gate=new AtomicBoolean(false);var cycle=new ReportPreparationCycle(new JdbcReportSchedulePages(f.f.source),preparation,noUpdates,new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.f.source),Clock.fixed(Instant.parse("2026-02-01T00:00:00Z"),ZoneOffset.UTC),gate::get);assertEquals(ReportPreparationCycle.Outcome.GATED,cycle.run(()->true));assertEquals(ReportPreparationCycle.Outcome.IDLE,cycle.run(()->false));verifyNoInteractions(preparation,noUpdates);gate.set(true);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);when(preparation.prepare(any())).thenAnswer(i->{entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));throw new IllegalStateException("fictional preparation failure");});var executor=Executors.newSingleThreadExecutor();try{var first=executor.submit(()->cycle.run(()->true));assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(ReportPreparationCycle.Outcome.BUSY,cycle.run(()->true));release.countDown();assertEquals(ReportPreparationCycle.Outcome.RECOVERY_REQUIRED,first.get(5,TimeUnit.SECONDS));}finally{release.countDown();executor.shutdownNow();}verifyNoInteractions(noUpdates);assertThrows(RuntimeException.class,()->f.rr(()->cycle.run(()->true)));}
